SELECT f.festival_number, f.status, t.tag_name, f.festival_name, f.start_date, f.end_date, f.progress_status, f.address, ( SELECT COUNT(*) FROM festival_likes fl WHERE fl.festival_number = f.festival_number ) festivalLikes FROM festivals f LEFT JOIN add_tags at ON at.festival_number = f.festival_number AND at.is_main = 1 LEFT JOIN tags t ON t.tag_number = at.tag_number
AND f.status = #{query.filterByStatus}
AND f.progress_status = #{query.filterByProgressStatus}
AND f.festival_name LIKE CONCAT('%', #{query.keyword}, '%')
AND t.tag_name LIKE CONCAT('%', #{query.keyword}, '%')

SELECT t.tag_name
FROM tags t
JOIN add_tags at ON at.tag_number = t.tag_number
WHERE at.festival_number = #{festivalNumber}
AND at.is_main = 1;

SELECT t.tag_name
FROM tags t
JOIN add_tags at ON at.tag_number = t.tag_number
WHERE at.festival_number = #{festivalNumber}
AND at.is_main = 0;

SELECT COUNT(*)
FROM festival_likes fl
WHERE fl.festival_number = #{festivalNumber};

SELECT COUNT(fr_like.festival_number)
FROM festival_reviews fr_like
WHERE fr_like.festival_number = #{festivalNumber}
AND fr_like.review = #{review};

mapper.update:
UPDATE festivals
SET status = 1 - status
WHERE festival_number = #{festivalNumber};
